	UPDATE KEPRQDT /*updateFileUpload*/
       SET IMAGE_KEY     = #{st_image_key}
         , PRE_GR_FLAG   = #{st_pre_gr_flag}
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND STATUS       <> 'D'


	UPDATE KEPQTDT /*saveMasterMpRqClose*/
       SET ADMIN_CLOSE_FLAG = 'Y'
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND STATUS       = 'C'

