/*selectBuyerRate*/
	SELECT NVL(A.TOT_RATE,0) AS BUYER_RATE
        FROM TBL_BUYER_PRIMECOST_MNG A
        WHERE A.BUYER=#{st_buyer}
        AND A.STATUS='C'
        AND A.PRIMECOST_STATUS='Y'


/*selectBuyerSum*/
	SELECT TO_NUMBER(#{param1}) * TO_NUMBER(#{param2}) AS D_SUM
        FROM DUAL


/*selectBuyerSumB*/
	SELECT TO_NUMBER(#{param1}) /(1-( TO_NUMBER(#{param2})/100)) AS D_SUM
        FROM DUAL

mapper.update:

	UPDATE KEPRQDT /*saveRQDT*/
      SET ATOB_UNIT_PRICE   = 0         
          , IMAGE_KEY         = #{st_image_key}
          , PROCESS_TYPE      = #{st_process_type}
          , IMPORT_FLAG       = #{st_import_flag}
          , WAREHOUSE_CODE = #{st_warehouse_code}
          , BELOW_COMORG_CODE = #{st_below_comorg_code}
          , LOGISTICS_FEE     = NVL(#{st_logistics_fee},0)
          , RFQ_KEP_USER      = #{USER_ID}
          , RFQ_DATE          = SYSDATE               
          , PRE_GR_FLAG = #{st_pre_gr_flag}
          , RFQ_IMG_TYPE = #{st_img_type}
          , IMGFILE_DIR = #{st_imgfile_dir}
          , IMGFILE_NAME = #{st_imgfile_name}
          , SAFETY_FLAG = #{st_safety_flag}
          , ITEM_MAKE_TYPE = #{st_item_make_type}
          , PRE_GR_USER_NAME = #{st_pre_gr_user_name}
          , PRE_GR_DEPT_NAME = #{st_pre_gr_dept_name}
          , ONLINE_PRICE = #{st_online_price}
          , ONLINE_PRICE_REASON = #{st_online_price_reason}



          , ORIGIN_NAME       = (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=#{ORIGIN_CODE})
          , ORIGIN_CODE       = #{ORIGIN_CODE}
          , MAKER_NAME       = #{MAKER_NAME}
          , MAKER_CODE 		 = #{MAKER_CODE}






          , ORIGIN_CODE = #{st_rqdt_origin_code}
          , ORIGIN_NAME = (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE=#{st_rqdt_origin_code})



     	 , KEP_RATE = NVL(#{RATE},0)
     	 , TAX_TYPE = DECODE(#{st_rqdt_tax_type}, '', '11', #{st_rqdt_tax_type})
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND STATUS <> 'D'


	UPDATE KEPQTDT /*saveQTDT*/
       SET ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
          , BID_SUCCESS_FLAG   = DECODE(#{AGENT_CHECK},'1','Y','N')
          , BID_SUCCESS_CODE   = DECODE(#{AGENT_CHECK},'1',#{st_bid_success_code},'')
          , BID_SUCCESS_REASON = DECODE(#{AGENT_CHECK},'1',#{st_bid_success_reason},'')
          , BID_SUCCESS_KEP   = DECODE(#{AGENT_CHECK},'1',#{USER_ID},'')
          , BID_SUCCESS_DATM = DECODE(#{AGENT_CHECK},'1',SYSDATE,'')
          , MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
          , PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
          , SELLER_AREA = #{SELLER_AREA}
          , AGENT_CHOICE_SEQ = DECODE(#{AGENT_CHECK},'1',#{st_agent_choice_seq},'')
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND AGENT = #{AGENT}
       AND AGENT_REVISION = #{AGENT_REVISION}
       AND STATUS <> 'D'


	UPDATE KEPQTDT /*saveSgQTDT*/
       SET BID_SUCCESS_FLAG   = DECODE(#{AGENT_CHECK},'1','Y','N')
          , BID_SUCCESS_CODE   = DECODE(#{AGENT_CHECK},'1',#{st_bid_success_code},'')
          , BID_SUCCESS_REASON = DECODE(#{AGENT_CHECK},'1',#{st_bid_success_reason},'')
          , BID_SUCCESS_KEP   = DECODE(#{AGENT_CHECK},'1',#{USER_ID},'')
          , BID_SUCCESS_DATM = DECODE(#{AGENT_CHECK},'1',SYSDATE,'')
          , MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
          , PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
          , SELLER_AREA = #{SELLER_AREA}
          , AGENT_CHOICE_SEQ = DECODE(#{AGENT_CHECK},'1',#{st_agent_choice_seq},'')
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND AGENT = #{AGENT}
       AND AGENT_REVISION = #{AGENT_REVISION}
       AND STATUS <> 'D'


		UPDATE KEPQTDT /*savePmQTDT*/
	       SET ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
			, MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
          	, PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
          	, SELLER_AREA = #{SELLER_AREA}
	     WHERE BUYER         = #{st_buyer}
	       AND QUOTATION_NO  = #{st_quotation_no}
	       AND QUOTATION_SEQ = #{st_quotation_seq}
	       AND REVISION      = #{st_revision}
	       AND AGENT = #{AGENT}
	       AND AGENT_REVISION = #{AGENT_REVISION}
	       AND STATUS <> 'D'


	UPDATE KEPRQDT /*saveMasterMpRqMarketUnitPriceYn*/
       SET MARKET_UNIT_PRICE_YN = 'Y'
          ,ONLINE_URL = #{ONLINE_URL}
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND STATUS <> 'D'
